    async def create_builder_session(
        self,
        id: str,
        *,
        expires_in: typing.Optional[int] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> SignBuilderSession:
        """
        A short-lived link to the embedded builder for this template: upload documents, add roles, and drag fields onto pages. Embed it with `mountBuilder` from `coss/sign` (from an origin in your Sign settings' `allowed_origins`) for whoever edits the template.

        Parameters
        ----------
        id : str
            The template's id.

        expires_in : typing.Optional[int]
            Seconds until the link expires: default 3600, at most 86400.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        SignBuilderSession
            The builder session, with its link.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.sign.templates.create_builder_session(
                id="stpl_01k7c8m4q2f3e9v6t5r1n0p8yz",
                expires_in=3600,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_builder_session(
            id, expires_in=expires_in, request_options=request_options
        )
        return _response.data
